<?php
declare(strict_types=1);requireRole('subject-officer');require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/activity.php';$activePage='distribute-items';$errors=[];$success=(string)($_SESSION['flash_success']??'');unset($_SESSION['flash_success']);$db=database();$user=(int)$_SESSION['user_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){$id=filter_input(INPUT_POST,'fulfillment_id',FILTER_VALIDATE_INT);$action=(string)($_POST['action']??'');$sso=filter_input(INPUT_POST,'sso_id',FILTER_VALIDATE_INT);if(!verifyCsrfToken((string)($_POST['csrf_token']??'')))$errors[]='Your session expired.';if(!$id||!in_array($action,['distribute','handover'],true))$errors[]='Invalid fulfillment action.';if($action==='handover'&&!$sso)$errors[]='Select the beneficiary division SSO.';if(!$errors){try{$db->beginTransaction();$q=$db->prepare("SELECT f.*,ar.beneficiary_id,ar.item_id,ar.quantity,b.ds_division_id FROM goods_fulfillments f JOIN aid_requests ar ON ar.id=f.aid_request_id JOIN beneficiaries b ON b.id=ar.beneficiary_id WHERE f.id=:id AND f.subject_officer_id=:user AND f.status='with-subject-officer' FOR UPDATE");$q->execute(['id'=>$id,'user'=>$user]);$f=$q->fetch();if(!$f)throw new RuntimeException('This item is no longer available in your custody.');if($action==='handover'){$q=$db->prepare("SELECT id FROM users WHERE id=:sso AND role='social-service-officer' AND status='active' AND ds_division_id=:division");$q->execute(['sso'=>$sso,'division'=>$f['ds_division_id']]);if(!$q->fetchColumn())throw new RuntimeException('The selected SSO is not assigned to the beneficiary division.');$db->prepare("UPDATE goods_fulfillments SET status='pending-sso-handover',sso_id=:sso,handed_to_sso_at=NOW() WHERE id=:id")->execute(['sso'=>$sso,'id'=>$id]);$message='Item handed to the division SSO.';}else{$insert=$db->prepare("INSERT INTO distributions(aid_request_id,beneficiary_id,item_id,quantity,distribution_type,source,distributed_by) VALUES(:aid,:beneficiary,:item,:quantity,'request-based','officer-pool',:user)");$insert->execute(['aid'=>$f['aid_request_id'],'beneficiary'=>$f['beneficiary_id'],'item'=>$f['item_id'],'quantity'=>$f['quantity'],'user'=>$user]);$db->prepare("UPDATE goods_fulfillments SET status='distributed',distributed_at=NOW() WHERE id=:id")->execute(['id'=>$id]);$db->prepare("UPDATE aid_requests SET status='distributed' WHERE id=:id")->execute(['id'=>$f['aid_request_id']]);$message='Item distributed directly to the beneficiary.';}$db->commit();logActivity('Goods Fulfillment',$message,'FUL-'.str_pad((string)$id,4,'0',STR_PAD_LEFT),$action);$_SESSION['flash_success']=$message;unset($_SESSION['csrf_token']);header('Location: dashboard.php?page=distribute-items');exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log($e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'Unable to process item.';}}}
try{$q=$db->prepare("SELECT f.*,ar.quantity,ar.prescribed_power,b.full_name,b.nic,b.address,b.ds_division_id,i.item_name,i.variety,ds.name division_name FROM goods_fulfillments f JOIN aid_requests ar ON ar.id=f.aid_request_id JOIN beneficiaries b ON b.id=ar.beneficiary_id JOIN inventory_items i ON i.id=ar.item_id JOIN ds_divisions ds ON ds.id=b.ds_division_id WHERE f.subject_officer_id=:user ORDER BY FIELD(f.status,'with-subject-officer','pending-sso-handover','distributed'),f.id DESC");$q->execute(['user'=>$user]);$rows=$q->fetchAll();$officers=$db->query("SELECT id,full_name,ds_division_id FROM users WHERE role='social-service-officer' AND status='active' ORDER BY full_name")->fetchAll();}catch(PDOException $e){error_log($e->getMessage());$rows=$officers=[];$errors[]='Fulfillment queue is unavailable.';}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Final Distribution | WIDMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/admin-dashboard.css" rel="stylesheet"></head><body><?php require __DIR__.'/../../includes/subject-officer-sidebar.php';?><div class="admin-shell"><header class="topbar"><h1>Final Distribution and SSO Handover</h1></header><main class="dashboard-content"><?php if($success):?><div class="alert alert-success"><?=htmlspecialchars($success)?></div><?php endif;?><?php if($errors):?><div class="alert alert-danger"><?=htmlspecialchars(implode(' ',$errors))?></div><?php endif;?><section class="admin-data-card"><div class="admin-data-header"><h2>Items Released to Me</h2></div><div class="admin-data-table-wrap"><table class="admin-data-table"><thead><tr><th>Ref</th><th>Beneficiary</th><th>NIC / Address</th><th>Item</th><th>Lens Match</th><th>Division</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8">No released items.</td></tr><?php else:foreach($rows as $r):?><tr><td>FUL-<?=str_pad((string)$r['id'],4,'0',STR_PAD_LEFT)?></td><td><?=htmlspecialchars($r['full_name'])?></td><td><?=htmlspecialchars($r['nic'])?><small><?=htmlspecialchars($r['address'])?></small></td><td><?=htmlspecialchars($r['item_name'].($r['variety']?' — '.$r['variety']:''))?> × <?=(int)$r['quantity']?></td><td><?=$r['lens_unit_identifier']?htmlspecialchars($r['lens_unit_identifier']).' / '.sprintf('%+.2f',(float)$r['prescribed_power']):'—'?></td><td><?=htmlspecialchars($r['division_name'])?></td><td><?=htmlspecialchars(str_replace('-',' ',$r['status']))?></td><td><?php if($r['status']==='with-subject-officer'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken())?>"><input type="hidden" name="fulfillment_id" value="<?=(int)$r['id']?>"><button name="action" value="distribute" class="approve-button">Distributed Directly</button><select name="sso_id"><option value="">Beneficiary unavailable — select SSO</option><?php foreach($officers as $o):if((int)$o['ds_division_id']===(int)$r['ds_division_id']):?><option value="<?=(int)$o['id']?>"><?=htmlspecialchars($o['full_name'])?></option><?php endif;endforeach;?></select><button name="action" value="handover" class="admin-primary-action">Hand to SSO</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><script src="assets/js/admin-dashboard.js"></script></body></html>
